event_examples.MessageEvent:
@client.on_message(filters.incoming & filters.text)
async def handler(event):
    await event.reply("Received")

event_examples.ReadHistoryEvent:
@client.on_read_history()
async def handler(event):
    print(event.chat_id, event.max_id, event.outbox)

event_examples.CallbackQueryEvent:
@client.on_callback_query(filters.data("confirm"))
async def handler(event):
    await event.answer("Confirmed", alert=False)

event_examples.InlineQueryEvent:
@client.on_inline_query()
async def handler(event):
    await event.answer([buttons.article("one", "Title", "Body")], cache_time=30)
